package com.petcare.backend.service.impl;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.petcare.backend.exception.*;import com.petcare.backend.model.*;import com.petcare.backend.repository.*;import com.petcare.backend.service.SocialPermissionService;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.*;import org.springframework.data.domain.PageImpl;
@ExtendWith(MockitoExtension.class) @MockitoSettings(strictness=org.mockito.quality.Strictness.LENIENT) class NotificationServiceImplTest{@Mock NotificationRepository repo;@Mock SocialPermissionService permissions;@Mock UserRepository users;NotificationServiceImpl service;@BeforeEach void init(){service=new NotificationServiceImpl(repo,permissions,users);when(repo.save(any())).thenAnswer(i->i.getArgument(0));}User u(long id){User u=new User();u.setId(id);return u;}@Test void createNotification_NullAndExistingSenderReferencePartitions(){when(users.findById(1L)).thenReturn(Optional.of(u(1)));service.createNotification(1L,null,"t","b","x",null);verify(repo).save(argThat(n->n.getSender()==null&&n.getData()==null));when(users.findById(2L)).thenReturn(Optional.of(u(2)));service.createNotification(1L,2L,"t","b","x",9L);verify(repo,times(2)).save(any());when(users.findById(3L)).thenReturn(Optional.empty());assertThatThrownBy(()->service.createNotification(3L,null,"t","b","x",null)).isInstanceOf(ResourceNotFoundException.class);when(users.findById(8L)).thenReturn(Optional.empty());assertThatThrownBy(()->service.createNotification(1L,8L,"t","b","x",null)).isInstanceOf(ResourceNotFoundException.class);}
@Test void markRead_PaginationCountAndReadAllBranches(){Notification unread=new Notification();unread.setId(3L);unread.setReceiver(u(1));unread.setIsRead(false);when(repo.findByIdAndReceiver_Id(3L,1L)).thenReturn(Optional.of(unread));assertThat(service.markAsRead(1L,3L).getReferenceId()).isNull();assertThat(unread.getIsRead()).isTrue();assertThatThrownBy(()->service.markAsRead(1L,0L)).isInstanceOf(BadRequestException.class);when(repo.findByIdAndReceiver_Id(4L,1L)).thenReturn(Optional.empty());assertThatThrownBy(()->service.markAsRead(1L,4L)).isInstanceOf(ResourceNotFoundException.class);when(repo.findByReceiver_IdOrderByCreatedAtDesc(1L)).thenReturn(List.of(unread));service.markAllAsRead(1L);assertThatThrownBy(()->service.getMyNotifications(1L,-1,1)).isInstanceOf(BadRequestException.class);assertThatThrownBy(()->service.getMyNotifications(1L,0,0)).isInstanceOf(BadRequestException.class);when(repo.countByReceiver_IdAndIsReadFalse(1L)).thenReturn(2L);assertThat(service.countUnread(1L)).isEqualTo(2L);}
@Test void readAllAndMapping_AlreadyReadNullSenderAndReferenceBranches(){Notification read=new Notification();read.setId(5L);read.setReceiver(u(1));read.setIsRead(true);read.setData("not-json");when(repo.findByIdAndReceiver_Id(5L,1L)).thenReturn(Optional.of(read));assertThat(service.markAsRead(1L,5L).getSenderId()).isNull();verify(repo).save(read);when(repo.findByReceiver_IdOrderByCreatedAtDesc(1L)).thenReturn(List.of(),List.of(read));service.markAllAsRead(1L);service.markAllAsRead(1L);verify(repo,times(2)).findByReceiver_IdOrderByCreatedAtDesc(1L);}
@Test void mapping_ReferenceAndSenderPresent_AreExtracted(){Notification n=new Notification();n.setId(6L);n.setReceiver(u(1));n.setSender(u(2));n.setIsRead(false);n.setData("{\"referenceId\":77}");when(repo.findByIdAndReceiver_Id(6L,1L)).thenReturn(Optional.of(n));assertThat(service.markAsRead(1L,6L).getSenderId()).isEqualTo(2L);assertThat(service.markAsRead(1L,6L).getReferenceId()).isEqualTo(77L);}
@Test void getMyNotifications_MapsEmptyAndDataWithNullReceiver(){Notification nullReceiver=new Notification();nullReceiver.setId(7L);nullReceiver.setIsRead(false);Notification full=new Notification();full.setId(8L);full.setReceiver(u(1));full.setSender(u(2));full.setIsRead(true);when(repo.findByReceiver_IdOrderByCreatedAtDesc(eq(1L),any())).thenReturn(new PageImpl<>(List.of(nullReceiver,full)));var response=service.getMyNotifications(1L,0,99);assertThat(response.getContent()).hasSize(2);assertThat(response.getContent().get(0).getReceiverId()).isNull();assertThat(response.getContent().get(1).getSenderId()).isEqualTo(2L);verify(permissions).checkUserActive(1L);ArgumentCaptor<org.springframework.data.domain.Pageable> page=ArgumentCaptor.forClass(org.springframework.data.domain.Pageable.class);verify(repo).findByReceiver_IdOrderByCreatedAtDesc(eq(1L),page.capture());assertThat(page.getValue().getPageSize()).isEqualTo(50);when(repo.findByReceiver_IdOrderByCreatedAtDesc(eq(1L),any())).thenReturn(new PageImpl<>(List.of()));assertThat(service.getMyNotifications(1L,0,1).getContent()).isEmpty();}
@Test void markAllAsRead_UpdatesOnlyUnreadNotifications(){Notification unread=new Notification();unread.setIsRead(false);Notification alreadyRead=new Notification();alreadyRead.setIsRead(true);when(repo.findByReceiver_IdOrderByCreatedAtDesc(1L)).thenReturn(List.of(unread,alreadyRead));service.markAllAsRead(1L);assertThat(unread.getIsRead()).isTrue();assertThat(unread.getReadAt()).isNotNull();assertThat(alreadyRead.getReadAt()).isNull();verify(permissions).checkUserActive(1L);}
}
